// LEGACY: Quorum heartbeat HMAC via require('crypto').
// Prefer examples/n8n/quorum-signed-heartbeat.json (Crypto nodes) — no allow-list needed.
// This path needs NODE_FUNCTION_ALLOW_BUILTIN=crypto on the n8n process, then restart n8n.
// Env: QUORUM_WORKFLOW_ID, QUORUM_KEY_ID, QUORUM_HMAC_SECRET, QUORUM_BASE_URL
const crypto = require('crypto');

const workflowId = $env.QUORUM_WORKFLOW_ID || 'REPLACE_QUORUM_WORKFLOW_ID';
const keyId = $env.QUORUM_KEY_ID || 'REPLACE_KEY_ID';
const secret = $env.QUORUM_HMAC_SECRET || 'REPLACE_HMAC_SECRET';
const baseUrl = ($env.QUORUM_BASE_URL || 'http://quorum:3000').replace(/\/+$/, '');
const path = `/api/v1/workflows/${workflowId}/heartbeats`;

const bodyObj = {
  schemaVersion: 1,
  executedAt: new Date().toISOString(),
  status: 'success',
  itemsProcessed: 1,
  externalExecutionRef: `n8n-${Date.now()}`,
};
const bodyRaw = JSON.stringify(bodyObj);
const timestampSeconds = String(Math.floor(Date.now() / 1000));
const idempotencyKey = `n8n-${timestampSeconds}-${Math.random().toString(16).slice(2)}`;
const bodySha256Hex = crypto.createHash('sha256').update(bodyRaw, 'utf8').digest('hex');
const signingPayload = ['POST', path, timestampSeconds, idempotencyKey, bodySha256Hex].join('\n');
const signature = crypto.createHmac('sha256', secret).update(signingPayload, 'utf8').digest('hex');

return [{
  json: {
    url: `${baseUrl}${path}`,
    bodyRaw,
    headers: {
      'content-type': 'application/json',
      'x-quorum-key-id': keyId,
      'x-quorum-timestamp': timestampSeconds,
      'x-quorum-idempotency-key': idempotencyKey,
      'x-quorum-signature': signature,
    },
  },
}];
